-- scheduling v44 bank (2026-10-28): the goal bank, version 2, written by Claude as drafts (Guy's walkthrough). Run after scheduling-v44.sql, on TEST.
-- Safe to run again: a template the admin already approved or changed is left as it is. Generated by tools/bank2-sql.py from supabase/bank2/*.json.

-- the old bank (version 1 goals, the whole-plan templates) to the archive: kept as raw material, not offered any more
update public.mercury_library set active = false where scope = 'mercury' and ((kind = 'goal' and content ? 'ages' and not (content ? 'v')) or kind = 'plan');

-- the 11 treatment methods: what it is, who it fits, 3 principles, an example from the field, a well-known book
insert into public.mercury_library (scope, kind, title, description, draft) values ('mercury', 'method', 'ARC', 'מה היא: מסגרת לעבודה עם ילדים אחרי טראומה מורכבת, דרך המבוגרים והשגרה שסביבם. (Attachment, Regulation and Competency)
למי מתאימה: ילדים בסידור חוץ ביתי וצוותים של מסגרות מגורים.
עקרונות:
• התקשרות: מבוגרים קשובים, עקביים וצפויים
• ויסות: לזהות רגשות ולהירגע, קודם יחד ואחר כך לבד
• מסוגלות: בחירה, זהות חיובית ותפקוד
דוגמה מהשטח: טקס בוקר קבוע עם אותו מבוגר, ומד רגשות שבודקים פעמיים ביום.
לקריאה: Blaustein & Kinniburgh, Treating Traumatic Stress in Children and Adolescents', true) on conflict (scope, institution, kind, title) do update set description = excluded.description, active = true, draft = true where public.mercury_library.draft;
insert into public.mercury_library (scope, kind, title, description, draft) values ('mercury', 'method', 'DDP/PACE', 'מה היא: גישה שמתמקדת ביחסים בין הילד למבוגר אחרי טראומת היקשרות. PACE היא הדרך היומיומית: שובבות, קבלה, סקרנות ואמפתיה. (Dyadic Developmental Psychotherapy)
למי מתאימה: ילדים שקשה להם לסמוך על מבוגרים.
עקרונות:
• מקבלים את הרגש, גם כשמציבים גבול להתנהגות
• סקרנים לגבי מה שמאחורי ההתנהגות, בלי האשמה
• המבוגר אחראי לתקן את הקשר אחרי ריב
דוגמה מהשטח: אחרי התפרצות: מה קרה לך שם? במקום למה עשית את זה?
לקריאה: Daniel Hughes, Building the Bonds of Attachment', true) on conflict (scope, institution, kind, title) do update set description = excluded.description, active = true, draft = true where public.mercury_library.draft;
insert into public.mercury_library (scope, kind, title, description, draft) values ('mercury', 'method', 'TF-CBT', 'מה היא: טיפול קוגניטיבי-התנהגותי ממוקד טראומה, עם מחקר רב על יעילותו. (Trauma-Focused Cognitive Behavioral Therapy)
למי מתאימה: ילדים מגיל 3 עם תסמיני טראומה.
עקרונות:
• מיומנויות הרגעה ונשימה, מתורגלות בזמן רגוע
• זיהוי רגשות ומחשבות, והחלפת מחשבה קשה במשפט מעודד
• הנרטיב של הטראומה רק אצל המטפל/ת; הצוות מתרגל את המיומנויות
דוגמה מהשטח: נשימת בלון שמתרגלים כל יום, וברגע של כעס עושים אותה יחד.
לקריאה: Cohen, Mannarino & Deblinger, Treating Trauma and Traumatic Grief in Children and Adolescents', true) on conflict (scope, institution, kind, title) do update set description = excluded.description, active = true, draft = true where public.mercury_library.draft;
insert into public.mercury_library (scope, kind, title, description, draft) values ('mercury', 'method', 'Theraplay', 'מה היא: טיפול דרך משחק משותף של מבוגר וילד, שבונה קשר והיקשרות. (Theraplay)
למי מתאימה: ילדים עם קושי בקשר ובקבלת קרבה.
עקרונות:
• מבנה: המבוגר מוביל משחק צפוי ובטוח
• מעורבות וטיפוח: משחק נעים, קרוב ושמח
• אתגר קטן שמצליחים בו יחד
דוגמה מהשטח: 5 דקות ביום של ספירת אצבעות, קרם על הידיים או בועות.
לקריאה: Booth & Jernberg, Theraplay: Helping Parents and Children Build Better Relationships Through Attachment-Based Play', true) on conflict (scope, institution, kind, title) do update set description = excluded.description, active = true, draft = true where public.mercury_library.draft;
insert into public.mercury_library (scope, kind, title, description, draft) values ('mercury', 'method', 'ויסות חושי', 'מה היא: התאמת הסביבה והגירויים כדי שהגוף יוכל להירגע ולהשתתף. (Sensory regulation)
למי מתאימה: ילדים שמוצפים מרעש, ממגע או מתנועה, או שמחפשים גירוי.
עקרונות:
• קודם הגוף: ילד/ה מוצף/ת לא יכול/ה להקשיב
• כלים פשוטים: תנועה, לחץ עמוק, הפחתת רעש ואור
• הכלים זמינים תמיד, לא כפרס
דוגמה מהשטח: קופסת הרגעה אישית עם כדור לחיץ, אוזניות ושמיכה כבדה.
לקריאה: A. Jean Ayres, Sensory Integration and the Child', true) on conflict (scope, institution, kind, title) do update set description = excluded.description, active = true, draft = true where public.mercury_library.draft;
insert into public.mercury_library (scope, kind, title, description, draft) values ('mercury', 'method', 'NMT', 'מה היא: מודל של ברוס פרי: מתערבים לפי סדר ההתפתחות של המוח. (Neurosequential Model of Therapeutics)
למי מתאימה: כל ילד/ה אחרי טראומה מוקדמת.
עקרונות:
• קודם ויסות: קצב, תנועה וביטחון
• אחר כך קשר: מבוגר קשוב
• רק אז חשיבה ולמידה
דוגמה מהשטח: קפיצות או נדנוד קצבי לפני ששואלים מה קרה.
לקריאה: Bruce Perry & Maia Szalavitz, The Boy Who Was Raised as a Dog', true) on conflict (scope, institution, kind, title) do update set description = excluded.description, active = true, draft = true where public.mercury_library.draft;
insert into public.mercury_library (scope, kind, title, description, draft) values ('mercury', 'method', 'סמכות חדשה', 'מה היא: גישה של חיים עומר: סמכות של נוכחות ושל עקביות, בלי מאבק כוח ובלי אלימות. (Nonviolent Resistance (NVR))
למי מתאימה: מצבי התנגדות, תוקפנות והתנהגות מסכנת; צוותים והורים.
עקרונות:
• נוכחות: אני כאן ולא הולך/ת, גם כשקשה
• דחייה: לא מגיבים ברגע הסערה, חוזרים לנושא כשרגוע
• תמיכה: הצוות פועל יחד, לא מבוגר אחד לבד
דוגמה מהשטח: במקום להתווכח בסערה: נדבר על זה אחר כך, ואז חוזרים לנושא בערב.
לקריאה: Haim Omer, Nonviolent Resistance: A New Approach to Violent and Self-Destructive Children', true) on conflict (scope, institution, kind, title) do update set description = excluded.description, active = true, draft = true where public.mercury_library.draft;
insert into public.mercury_library (scope, kind, title, description, draft) values ('mercury', 'method', 'TBRI', 'מה היא: גישה לילדים מאומנה ומסידור חוץ ביתי: חיבור, העצמה ותיקון. (Trust-Based Relational Intervention)
למי מתאימה: ילדים שעברו פגיעה ומסגרות שאין בהן רק אנשי מקצוע.
עקרונות:
• חיבור: מבט, שם ומגע לפני כל בקשה
• העצמה: לענות על צרכים בסיסיים (מים, אוכל, תנועה) לפני שמצפים להתנהגות
• תיקון: עם בחירות ועשייה מחדש, לא עם עונש
דוגמה מהשטח: מה את/ה צריך/ה עכשיו? מים, הפסקה או חיבוק?
לקריאה: Karyn Purvis, David Cross & Wendy Sunshine, The Connected Child', true) on conflict (scope, institution, kind, title) do update set description = excluded.description, active = true, draft = true where public.mercury_library.draft;
insert into public.mercury_library (scope, kind, title, description, draft) values ('mercury', 'method', 'CPS', 'מה היא: גישה של רוס גרין: ילדים מתנהגים טוב כשהם יכולים. במקום עונש, פותרים בעיה יחד. (Collaborative & Proactive Solutions)
למי מתאימה: ילדים עם התפרצויות והתנהגות מאתגרת.
עקרונות:
• מזהים מראש את המצבים שקשים לילד/ה
• שואלים מה קורה, ומקשיבים באמת
• מחפשים יחד פתרון שמתאים לשני הצדדים
דוגמה מהשטח: בזמן רגוע: שמתי לב שקשה לך במעבר לארוחה. מה קורה?
לקריאה: Ross Greene, The Explosive Child', true) on conflict (scope, institution, kind, title) do update set description = excluded.description, active = true, draft = true where public.mercury_library.draft;
insert into public.mercury_library (scope, kind, title, description, draft) values ('mercury', 'method', 'מעגל הביטחון', 'מה היא: מודל של היקשרות: המבוגר הוא בסיס בטוח לצאת ממנו ונמל מבטחים לחזור אליו. (Circle of Security)
למי מתאימה: כל ילד/ה, ובמיוחד צעירים; שפה פשוטה לצוות.
עקרונות:
• בסיס בטוח: המבוגר זמין כשהילד/ה יוצא/ת לשחק ולחקור
• נמל מבטחים: המבוגר מקבל כשהילד/ה חוזר/ת במצוקה
• תמיד גדול, חזק, חכם וטוב יותר
דוגמה מהשטח: כשהילד/ה בא/ה בבכי: מתכופפים, מקבלים, ואחרי שנרגע/ת עוזרים לחזור לשחק.
לקריאה: Powell, Cooper, Hoffman & Marvin, The Circle of Security Intervention', true) on conflict (scope, institution, kind, title) do update set description = excluded.description, active = true, draft = true where public.mercury_library.draft;
insert into public.mercury_library (scope, kind, title, description, draft) values ('mercury', 'method', 'טיפול נרטיבי', 'מה היא: גישה שמתייחסת לחיים כסיפור, ומפרידה בין הילד/ה לבין הבעיה. (Narrative therapy)
למי מתאימה: ילדים עם דימוי עצמי שלילי, ועבודה על סיפור החיים.
עקרונות:
• הבעיה היא הבעיה, הילד/ה הוא/היא לא הבעיה
• מחפשים רגעים שבהם הבעיה לא ניצחה
• בונים יחד סיפור חלופי, של כוחות
דוגמה מהשטח: במקום אתה כועס: מתי הכעס מנסה לנצח אותך? ומתי ניצחת אותו?
לקריאה: Michael White & David Epston, Narrative Means to Therapeutic Ends', true) on conflict (scope, institution, kind, title) do update set description = excluded.description, active = true, draft = true where public.mercury_library.draft;

