insert into public.mercury_library (scope, kind, title, description, themes, category, methods, content, draft) values ('mercury', 'goal', 'להירגע בעזרת כלי הרגעה', 'להשתמש בדרך הרגעה שבחר/ה, עם מבוגר או לבד, כשהרגש חזק', array['ויסות רגשי']::text[], 'ויסות רגשי', array['ARC', 'ויסות חושי', 'NMT', 'TF-CBT', 'Theraplay', 'TBRI']::text[], '{"v": 2, "bank": 1, "review": 3, "avoid": "לא לשלוח לפינה השקטה כעונש; זו פינה של הרגעה", "strengths": ["שליטה עצמית", "התמדה", "אומץ", "בקשת עזרה", "סבלנות"], "skills": ["הירגעות בעזרת כלי"], "ages": {"2-5": {"targets": [{"id": "t1", "text": "נרגע/ת בתוך ויסות משותף עם מבוגר מוכר, תוך 10 דקות", "staff": "נרגע/ת כשאנחנו לידו/לידה, תוך כמה דקות", "scale": ["בוכה או משתולל/ת זמן רב גם עם מבוגר", "נרגע/ת רק אחרי זמן ארוך ומגע", "נרגע/ת עם מבוגר וכלי מוכר", "נרגע/ת מהר כשמבוגר מתקרב", "מבקש/ת מבוגר בעצמו/בעצמה ונרגע/ת"]}, {"id": "t2", "text": "מקבל/ת כלי חושי מוצע (שמיכה, בובה, נדנוד) ומשתמש/ת בו בזמן מצוקה", "staff": "מסכים/ה לקחת את השמיכה או הבובה כשקשה", "scale": ["דוחה כל כלי", "מקבל/ת כלי רק אחרי שנרגע/ת", "מקבל/ת כלי כשמציעים", "הולך/ת לכלי כשמזכירים", "לוקח/ת את הכלי בעצמו/בעצמה"]}, {"id": "t3", "text": "משתתף/ת בתרגיל נשימה משחקי (נוצה, בועות) בזמן רגוע", "staff": "משחק/ת איתנו במשחקי נשיפה כשרגוע", "scale": ["לא משתתף/ת", "מסתכל/ת מהצד", "משתתף/ת רגע", "משתתף/ת ונהנה/ית", "מבקש/ת את המשחק בעצמו/בעצמה"]}, {"id": "t4", "text": "מצביע/ה על פרצוף רגש שמתאים למה שהוא/היא מרגיש/ה", "staff": "מראה לנו בכרטיס איך הוא/היא מרגיש/ה", "scale": ["לא מגיב/ה", "מסתכל/ת על הכרטיסים", "מצביע/ה כשמבוגר שואל", "מצביע/ה ומוסיף/ה מילה", "אומר/ת את הרגש לבד"]}, {"id": "t5", "text": "חוזר/ת למשחק או לפעילות אחרי שנרגע/ת", "staff": "חוזר/ת לשחק אחרי שנרגע/ת", "scale": ["נשאר/ת מנותק/ת אחרי", "חוזר/ת רק עם מבוגר צמוד", "חוזר/ת אחרי הזמנה", "חוזר/ת אחרי זמן קצר", "חוזר/ת לבד ובשמחה"]}], "interventions": [{"id": "i1", "name": "מבוגר קרוב ורגוע", "what": "מתיישבים לגובה העיניים, קול רך ונמוך, מעט מילים, ונשארים עד שהגוף נרגע", "why": "הגוף של ילד/ה קטן/ה לומד להירגע מהגוף הרגוע של המבוגר", "freq": "ברגע של מצוקה", "approach": "NMT", "targets": ["t1", "t5"], "sentences": ["אני כאן איתך", "נושמים יחד, לאט", "את/ה בטוח/ה, אני לא הולך/ת"]}, {"id": "i2", "name": "שמיכה ובובה מוכרות", "what": "מציעים את החפץ המוכר בלי לדרוש, ומשאירים אותו בהישג יד", "why": "מגע וחפץ מוכר מרגיעים את מערכת העצבים", "freq": "ברגע של מצוקה", "approach": "ויסות חושי", "targets": ["t2", "t1"], "sentences": ["הבובה שלך פה", "רוצה את השמיכה?"]}, {"id": "i3", "name": "נדנוד וקצב", "what": "נדנוד עדין, שיר שקט בקצב איטי, או טפיחה קצבית על הגב אם הילד/ה רוצה", "why": "קצב חוזר מווסת את הגוף לפני כל מילה", "freq": "ברגע של מצוקה, ופעם ביום בזמן רגוע", "approach": "NMT", "targets": ["t1"], "sentences": ["לאט לאט, כמו בסירה", "אני שר/ה לך"]}, {"id": "i4", "name": "משחק נשיפה", "what": "נושפים יחד על נוצה, בועות סבון או כדור צמר גפן, כמשחק", "why": "נשימה איטית נלמדת דרך משחק, ובזמן רגוע היא נשמרת לרגע הקשה", "freq": "פעם ביום, 5 דקות, בזמן רגוע", "approach": "TF-CBT", "targets": ["t3"], "sentences": ["בוא/י נעיף את הנוצה", "נושפים לאט, כמו על נר"]}, {"id": "i5", "name": "משחק טיפוח", "what": "משחק קצר של קרם על הידיים, ספירת אצבעות או כרית רכה, בלי דרישות", "why": "טיפוח נעים בונה קשר שבו הילד/ה מרגיש/ה מוחזק/ת", "freq": "פעם ביום, 5 דקות", "approach": "Theraplay", "targets": ["t1", "t5"], "sentences": ["אני סופר/ת לך את האצבעות", "איזה ידיים יפות יש לך"]}, {"id": "i6", "name": "כרטיסי רגשות", "what": "מראים שלושה פרצופים פשוטים ושואלים איך מרגישים עכשיו", "why": "מילה לרגש מפחיתה את העוצמה שלו", "freq": "אחרי שנרגע/ת, ובערב", "approach": "ARC", "targets": ["t4"], "sentences": ["איזה פרצוף את/ה עכשיו?", "היית כועס/ת, ועכשיו רגוע/ה"]}, {"id": "i7", "name": "שאלת צורך", "what": "פונים לילד/ה בקול רך ושואלים מה הוא/היא צריך/ה: מים, חיבוק או לשבת", "why": "ילד/ה שלומד/ת שהצורך שלו/שלה נענה, סומך/ת יותר על מבוגרים", "freq": "ברגע של קושי", "approach": "TBRI", "targets": ["t1", "t2"], "sentences": ["מה את/ה צריך/ה עכשיו?", "רוצה מים או חיבוק?"]}, {"id": "i8", "name": "חזרה עדינה לפעילות", "what": "אחרי שנרגע/ת, מזמינים בחיוך לחזור למשחק, ומתחילים בו יחד", "why": "החזרה מראה לילד/ה שהקושי עבר והקשר נשאר", "freq": "אחרי כל רגע קשה", "approach": "ARC", "targets": ["t5"], "sentences": ["רוצה לחזור לבנות איתי?", "עבר. בוא/י נמשיך"]}]}, "5-8": {"targets": [{"id": "t1", "text": "בוחר/ת כלי מקופסת ההרגעה ומשתמש/ת בו עם תזכורת של מבוגר", "staff": "משתמש/ת בכלי מהקופסה כשמזכירים לו/לה", "scale": ["מתפרץ/ת ולא מגיע/ה לכלי", "מגיע/ה לכלי רק אחרי שנרגע/ת", "משתמש/ת בכלי עם מבוגר צמוד", "משתמש/ת בכלי אחרי תזכורת קצרה", "בוחר/ת כלי בעצמו/בעצמה בזמן"]}, {"id": "t2", "text": "מזהה סימן גוף מוקדם (אגרופים, חום בפנים) לפני התפרצות", "staff": "מראה או אומר/ת שהגוף מתחיל לכעוס", "scale": ["לא מזהה בכלל", "מזהה בדיעבד עם מבוגר", "מזהה כשמבוגר מצביע", "אומר/ת סימן בזמן", "מזהה ופועל/ת להרגעה"]}, {"id": "t3", "text": "משתמש/ת בנשימה איטית (בלון, נר) ברגע של כעס", "staff": "עושה את נשימת הבלון כשכועס/ת", "scale": ["לא מסכים/ה", "עושה רק במשחק", "עושה עם מבוגר שנושם איתו/איתה", "עושה אחרי תזכורת", "עושה לבד"]}, {"id": "t4", "text": "מבקש/ת הפסקה במילים או בכרטיס במקום להתפרץ", "staff": "מבקש/ת הפסקה במקום לצעוק או להכות", "scale": ["מתפרץ/ת בלי לבקש", "בורח/ת בלי לומר", "מבקש/ת אחרי שמבוגר מציע", "מבקש/ת עם הכרטיס", "מבקש/ת במילים בזמן"]}, {"id": "t5", "text": "חוזר/ת לפעילות תוך 15 דקות אחרי רגע קשה", "staff": "חוזר/ת לפעילות אחרי שנרגע/ת", "scale": ["נשאר/ת מנותק/ת שעות", "חוזר/ת רק בפעילות הבאה", "חוזר/ת עם הזמנה", "חוזר/ת אחרי זמן קצר", "חוזר/ת לבד"]}], "interventions": [{"id": "i1", "name": "קופסת הרגעה אישית", "what": "מכינים יחד קופסה עם 3–4 כלים שהילד/ה בחר/ה (כדור לחיץ, תמונה, מוזיקה), ומתרגלים בזמן רגוע", "why": "כלי שהילד/ה בחר/ה בעצמו/בעצמה עובד טוב יותר מכלי שקיבל/ה", "freq": "מכינים פעם אחת; מתרגלים פעמיים בשבוע", "approach": "ויסות חושי", "targets": ["t1"], "sentences": ["איזה כלי יעזור לך עכשיו?", "הקופסה שלך פה"]}, {"id": "i2", "name": "מד הרגשות", "what": "מד צבעוני מ-1 עד 5. שואלים כמה חזק זה עכשיו, ומה עושים בכל מדרגה", "why": "מדידה הופכת רגש מציף למשהו שאפשר לטפל בו", "freq": "פעמיים ביום, ובכל רגע קשה", "approach": "ARC", "targets": ["t2", "t4"], "sentences": ["כמה חזק זה עכשיו, מ-1 עד 5?", "במדרגה 3 לוקחים הפסקה"]}, {"id": "i3", "name": "מפת הגוף", "what": "מציירים יחד גוף ומסמנים איפה מרגישים כעס, פחד ושמחה", "why": "חיבור בין תחושה בגוף לרגש מאפשר לזהות מוקדם", "freq": "פעם בשבוע, בזמן רגוע", "approach": "TF-CBT", "targets": ["t2"], "sentences": ["איפה בגוף את/ה מרגיש/ה את הכעס?", "הידיים שלך אומרות שמשהו קשה"]}, {"id": "i4", "name": "נשימת בלון", "what": "שואפים כאילו מנפחים בלון בבטן, ונושפים לאט. מתרגלים במשחק, ובכעס עושים יחד", "why": "נשימה איטית מורידה את העוררות של הגוף", "freq": "פעם ביום, 3 דקות, וברגע של כעס", "approach": "TF-CBT", "targets": ["t3"], "sentences": ["בוא/י ננפח את הבלון יחד", "עוד נשימה אחת, לאט"]}, {"id": "i5", "name": "כרטיס הפסקה", "what": "כרטיס שהילד/ה מניח/ה על השולחן כשצריך/ה הפסקה. מכבדים אותו מיד ובודקים אחר כך", "why": "דרך קלה לבקש עזרה מחליפה את ההתפרצות", "freq": "זמין כל הזמן", "approach": "CPS", "targets": ["t4"], "sentences": ["ראיתי את הכרטיס, קח/י את הזמן", "טוב שביקשת הפסקה"]}, {"id": "i6", "name": "שאלת צורך", "what": "בקול שקט: מה את/ה צריך/ה עכשיו? נותנים 2–3 אפשרויות", "why": "כשהצורך נענה, ההתנהגות נרגעת", "freq": "ברגע של קושי", "approach": "TBRI", "targets": ["t1", "t4"], "sentences": ["מה את/ה צריך/ה עכשיו?", "מים, הפסקה או לשבת לידי?"]}, {"id": "i7", "name": "תנועה מווסתת", "what": "קפיצות, דחיפת קיר או הליכה מהירה יחד, לפני שמדברים", "why": "תנועה פורקת את המתח מהגוף ומחזירה אותו לאיזון", "freq": "ברגע של עוררות גבוהה, ופעם בבוקר", "approach": "NMT", "targets": ["t1", "t5"], "sentences": ["בוא/י נקפוץ 10 פעמים", "נדחוף את הקיר חזק"]}, {"id": "i8", "name": "סקרנות אחרי", "what": "אחרי שנרגע/ת, שואלים בסקרנות ובלי שיפוט מה קרה, ומה עזר", "why": "שיחה רגועה אחרי מלמדת מה עובד לפעם הבאה", "freq": "אחרי כל רגע קשה", "approach": "DDP/PACE", "targets": ["t5", "t2"], "sentences": ["מה קרה לך שם?", "מה עזר לך להירגע הפעם?"]}]}}}'::jsonb, true) on conflict (scope, institution, kind, title) do update set description = excluded.description, themes = excluded.themes, category = excluded.category, methods = excluded.methods, content = excluded.content, active = true, draft = true where public.mercury_library.draft;

