insert into public.mercury_library (scope, kind, title, description, themes, category, methods, content, draft) values ('mercury', 'goal', 'לפנות למבוגר בטוח כשקשה', 'לזהות מבוגר שאפשר לסמוך עליו ולפנות אליו ברגע של קושי', array['ביטחון ויציבות']::text[], 'ביטחון ויציבות', array['ARC', 'מעגל הביטחון', 'Theraplay', 'DDP/PACE', 'TBRI', 'סמכות חדשה']::text[], '{"v": 2, "bank": 1, "review": 3, "avoid": "לא להעניש על פנייה בדרך לא נעימה; מחזקים את עצם הפנייה", "strengths": ["בקשת עזרה", "אומץ", "כנות", "קבלה", "חברות"], "skills": ["בקשת עזרה"], "ages": {"2-5": {"targets": [{"id": "t1", "text": "בא/ה למבוגר מוכר כשנפגע/ת או נבהל/ת, במקום להסתתר", "staff": "בא/ה אלינו כשכואב או מפחיד", "scale": ["מסתתר/ת או ממשיך/ה כאילו לא קרה", "מקבל/ת עזרה רק כשמבוגר ניגש", "בא/ה למבוגר אחד מוכר", "בא/ה לכמה מבוגרים מוכרים", "בא/ה מיד ומבקש/ת נחמה"]}, {"id": "t2", "text": "מאפשר/ת למבוגר לנחם (חיבוק, ידיים, נדנוד)", "staff": "מסכים/ה שנחבק או נרגיע", "scale": ["דוחה כל מגע", "מקבל/ת מגע רק אחרי זמן", "מקבל/ת מגע ממבוגר אחד", "מקבל/ת נחמה בקלות", "מבקש/ת נחמה בעצמו/בעצמה"]}, {"id": "t3", "text": "מבחין/ה בין מבוגרים מוכרים לזרים", "staff": "מעדיף/ה את המבוגרים הקבועים על פני זרים", "scale": ["הולך/ת לכל זר", "נצמד/ת לכל מבוגר שמגיע", "מעדיף/ה מבוגרים מוכרים לפעמים", "פונה בעיקר למוכרים", "זהיר/ה עם זרים ופונה למוכרים"]}, {"id": "t4", "text": "נפרד/ת ממבוגר בסוף משמרת בטקס קבוע, ומקבל/ת את הבא", "staff": "נפרד/ת מאיתנו בסוף משמרת בלי להתפרק", "scale": ["מתפרק/ת בכל פרידה", "נרגע/ת רק אחרי זמן ארוך", "נפרד/ת עם טקס ותמיכה", "נפרד/ת עם תזכורת לטקס", "נפרד/ת ומקבל/ת את הבא בקלות"]}, {"id": "t5", "text": "חוזר/ת לשחק אחרי שקיבל/ה נחמה (בסיס בטוח)", "staff": "אחרי חיבוק חוזר/ת לשחק", "scale": ["נשאר/ת נצמד/ת או מנותק/ת", "חוזר/ת רק עם המבוגר", "חוזר/ת ומסתכל/ת על המבוגר", "חוזר/ת לשחק בביטחון", "חוזר/ת ומשתף/ת את המבוגר במשחק"]}], "interventions": [{"id": "i1", "name": "נמל מבטחים", "what": "כשהילד/ה נפגע/ת או נבהל/ת: ניגשים מיד, מתכופפים, מציעים ידיים ומחכים לתנועה שלו/שלה", "why": "ילד/ה שחו